bool Fenrir::Generated::RegisterFixtureTypes(Fenrir::TypeRegistry& registry)
{
    // As the description lists them: a type after every type its fields name.
    constexpr const Fenrir::TypeDescription* descriptions[] = {
        &Fixture_Handle,
        &Fixture_Limits,
        &Fixture_Marker,
        &Fixture_Motion,
        &Fixture_Offset,
        &Fixture_Numbers,
        &Fixture_Quat,
        &Fixture_Spring,
        &Fixture_Vec3,
        &Fixture_Body,
        &Fixture_BodyId,
        &Fixture_BoxShape,
        &Fixture_Clock,
        &Fixture_ShapeType,
        &Fixture_SphereShape,
        &Fixture_Columns,
        &Fixture_Contacts,
        &Fixture_Dial,
        &Fixture_Folder,
        &Fixture_Heading,
        &Fixture_Hit,
        &Fixture_Pair_double,
        &Fixture_Size,
        &Fixture_Socket,
        &Fixture_Tag,
        &Fixture_Ticket,
        &Fixture_Touched,
        &Fixture_Weather,
    };
    bool registered = true;
    for (const Fenrir::TypeDescription* description : descriptions)
        registered = registry.Register(*description) && registered;
    return registered;
}

